create table if not exists public.betalink_wallets (user_id uuid primary key references auth.users(id) on delete cascade, balance integer not null default 0 check(balance>=0), lifetime_earned integer not null default 0 check(lifetime_earned>=0), completed_support_tests integer not null default 0 check(completed_support_tests>=0), updated_at timestamptz not null default now());
create table if not exists public.betalink_wallet_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, amount integer not null check(amount<>0), entry_type text not null check(entry_type in ('test_reward','campaign_create','group_create','group_join','admin_adjustment')), description text not null default '', campaign_id uuid references public.campaigns(id) on delete set null, group_id uuid references public.tester_groups(id) on delete set null, created_at timestamptz not null default now());
create unique index if not exists betalink_test_reward_once on public.betalink_wallet_ledger(user_id,campaign_id,entry_type) where entry_type='test_reward';
create index if not exists betalink_wallet_ledger_user_created on public.betalink_wallet_ledger(user_id,created_at desc);
alter table public.betalink_wallets enable row level security; alter table public.betalink_wallet_ledger enable row level security;
create policy betalink_wallet_read_self on public.betalink_wallets for select to authenticated using(user_id=(select auth.uid()));
create policy betalink_wallet_ledger_read_self on public.betalink_wallet_ledger for select to authenticated using(user_id=(select auth.uid()));
grant select on public.betalink_wallets,public.betalink_wallet_ledger to authenticated; revoke insert,update,delete on public.betalink_wallets,public.betalink_wallet_ledger from anon,authenticated;
create or replace function public.betalink_wallet_snapshot() returns table(balance integer,lifetime_earned integer,completed_support_tests integer) language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'Oturum gerekli.'; end if; insert into public.betalink_wallets(user_id) values(uid) on conflict(user_id) do nothing; return query select w.balance,w.lifetime_earned,w.completed_support_tests from public.betalink_wallets w where w.user_id=uid; end; $$;
create or replace function public.betalink_award_test_reward() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.status='completed' and old.status is distinct from new.status and exists(select 1 from public.campaign_tracking ct where ct.campaign_id=new.campaign_id and ct.tracking_status='completed') then insert into public.betalink_wallets(user_id) values(new.tester_id) on conflict(user_id) do nothing; insert into public.betalink_wallet_ledger(user_id,amount,entry_type,description,campaign_id) values(new.tester_id,25,'test_reward','Tamamlanan uygulama testi ödülü',new.campaign_id) on conflict do nothing; if found then update public.betalink_wallets set balance=balance+25,lifetime_earned=lifetime_earned+25,completed_support_tests=completed_support_tests+1,updated_at=now() where user_id=new.tester_id; end if; end if; return new; end; $$;
revoke all on function public.betalink_award_test_reward() from public,anon,authenticated; drop trigger if exists betalink_reward_completed_test on public.campaign_members; create trigger betalink_reward_completed_test after update of status on public.campaign_members for each row execute function public.betalink_award_test_reward();
create or replace function public.betalink_create_campaign(p_app_name text,p_play_opt_in_url text,p_description text default '',p_category text default 'other',p_target_testers integer default 12,p_minimum_android_version integer default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); wallet public.betalink_wallets%rowtype; new_id uuid; begin if uid is null then raise exception 'Oturum gerekli.'; end if; if (select count(*) from public.betalink_wallets where user_id=uid and completed_support_tests>=2)=0 then raise exception 'Kampanya açmak için önce en az 2 uygulamanın testini tamamlamalısın.'; end if; if char_length(trim(p_app_name)) not between 2 and 100 or p_play_opt_in_url !~* '^https://' then raise exception 'Uygulama adı veya Google Play test bağlantısı geçersiz.'; end if; insert into public.betalink_wallets(user_id) values(uid) on conflict(user_id) do nothing; select * into wallet from public.betalink_wallets where user_id=uid for update; if wallet.balance<50 then raise exception 'Kampanya açmak için 50 BetaPuan gerekli. Mevcut bakiyen: %',wallet.balance; end if; insert into public.campaigns(developer_id,app_name,play_opt_in_url,description,category,target_testers,minimum_android_version,status) values(uid,trim(p_app_name),trim(p_play_opt_in_url),coalesce(p_description,''),coalesce(p_category,'other'),greatest(12,least(coalesce(p_target_testers,12),1000)),p_minimum_android_version,'open') returning id into new_id; update public.betalink_wallets set balance=balance-50,updated_at=now() where user_id=uid; insert into public.betalink_wallet_ledger(user_id,amount,entry_type,description,campaign_id) values(uid,-50,'campaign_create','Yeni test kampanyası oluşturma bedeli',new_id); return new_id; end; $$;
create or replace function public.betalink_create_group(p_name text,p_description text default '',p_is_private boolean default false) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); wallet public.betalink_wallets%rowtype; new_id uuid; begin if uid is null then raise exception 'Oturum gerekli.'; end if; if (select count(*) from public.betalink_wallets where user_id=uid and completed_support_tests>=2)=0 then raise exception 'Grup oluşturmak için önce en az 2 uygulamanın testini tamamlamalısın.'; end if; insert into public.betalink_wallets(user_id) values(uid) on conflict(user_id) do nothing; select * into wallet from public.betalink_wallets where user_id=uid for update; if wallet.balance<30 then raise exception 'Grup oluşturmak için 30 BetaPuan gerekli. Mevcut bakiyen: %',wallet.balance; end if; insert into public.tester_groups(name,description,is_private,created_by) values(trim(p_name),coalesce(p_description,''),coalesce(p_is_private,false),uid) returning id into new_id; insert into public.group_members(group_id,user_id,member_role,status) values(new_id,uid,'leader','approved'); update public.betalink_wallets set balance=balance-30,updated_at=now() where user_id=uid; insert into public.betalink_wallet_ledger(user_id,amount,entry_type,description,group_id) values(uid,-30,'group_create','Tester grubu oluşturma bedeli',new_id); return new_id; end; $$;
create or replace function public.betalink_join_group(p_group_id uuid) returns text language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); grp public.tester_groups%rowtype; wallet public.betalink_wallets%rowtype; cost integer:=5; begin if uid is null then raise exception 'Oturum gerekli.'; end if; if (select count(*) from public.betalink_wallets where user_id=uid and completed_support_tests>=2)=0 then raise exception 'Gruplara katılmak için önce en az 2 uygulamanın testini tamamlamalısın.'; end if; select * into grp from public.tester_groups where id=p_group_id; if not found then raise exception 'Grup bulunamadı.'; end if; if grp.created_by=uid then raise exception 'Kendi grubuna zaten sahipsin.'; end if; if exists(select 1 from public.group_members where group_id=p_group_id and user_id=uid) then raise exception 'Bu gruba zaten katılmışsın veya isteğin bekliyor.'; end if; if grp.is_private then insert into public.group_members(group_id,user_id,member_role,status) values(p_group_id,uid,'member','pending'); return 'pending'; end if; insert into public.betalink_wallets(user_id) values(uid) on conflict(user_id) do nothing; select * into wallet from public.betalink_wallets where user_id=uid for update; if wallet.balance<cost then raise exception 'Açık gruba katılmak için 5 BetaPuan gerekli. Mevcut bakiyen: %',wallet.balance; end if; insert into public.group_members(group_id,user_id,member_role,status) values(p_group_id,uid,'member','approved'); update public.betalink_wallets set balance=balance-cost,updated_at=now() where user_id=uid; insert into public.betalink_wallet_ledger(user_id,amount,entry_type,description,group_id) values(uid,-cost,'group_join','Açık tester grubuna katılım bedeli',p_group_id); return 'approved'; end; $$;
drop policy if exists campaigns_create_as_owner on public.campaigns; drop policy if exists groups_create_self on public.tester_groups; drop policy if exists group_members_join_self on public.group_members;
revoke all on function public.betalink_wallet_snapshot() from public,anon; revoke all on function public.betalink_create_campaign(text,text,text,text,integer,integer) from public,anon; revoke all on function public.betalink_create_group(text,text,boolean) from public,anon; revoke all on function public.betalink_join_group(uuid) from public,anon;
grant execute on function public.betalink_wallet_snapshot() to authenticated; grant execute on function public.betalink_create_campaign(text,text,text,text,integer,integer) to authenticated; grant execute on function public.betalink_create_group(text,text,boolean) to authenticated; grant execute on function public.betalink_join_group(uuid) to authenticated;